mapper.select:
select

from dish d
left join dish_category c on c.id = d.category_id and c.family_id = d.family_id

    inner join dish_tag_relation dtr on dtr.dish_id = d.id and dtr.tag_id = #{tagId}


    d.family_id = #{familyId}
    and d.deleted = 0

        and (
            d.name like concat('%', #{keyword}, '%')
            or d.aliases like concat('%', #{keyword}, '%')
            or d.description like concat('%', #{keyword}, '%')
        )


        and d.category_id = #{categoryId}


        and d.status = #{status}


        and d.status = 'ACTIVE'


order by d.updated_at desc, d.id asc
